-- =============================================================================
-- Alloy — Firefly staging seed (SYNTHETIC, deterministic, idempotent) — ALY-14 E2
-- =============================================================================
-- GENERATED by web/lib/staging/fireflyStagingSeed/renderSql.ts. Do not edit by hand:
--   cd web && npm run staging:seed:firefly -- render
-- and commit the result. A test fails when this file and the renderer disagree.
--
-- Run it ONLY through the seed command, which resolves and refuses targets:
--   cd web && npm run staging:seed:firefly -- apply --target local
-- See docs/platform/governance/firefly-staging-seed.md.
--
-- Writes into the existing Firefly Early Learning org (93667019-bd28-49b5-a688-acc9bb1e0a19), the only staging school.
-- Creates no org. Writes only rows in the seed id namespace (f17e0000-0000-4000-8000-…) and never changes a
-- row it did not write — the tenant's own rows, every other org, every global row — the fence proves it.
-- Configuration the org already has is used as is; the seed authors only what a bare org lacks.
-- Every person is synthetic.
-- =============================================================================

\set ON_ERROR_STOP on

\if :{?seed_target}
\else
DO $refuse$ BEGIN
    RAISE EXCEPTION 'firefly_staging_seed: refused — seed_target is unset; run it through npm run staging:seed:firefly';
END $refuse$;
\endif

BEGIN ISOLATION LEVEL REPEATABLE READ;

-- Assign this transaction its id now, so age(xmin) <= 0 means "written by this transaction".
SELECT txid_current() IS NOT NULL AS transaction_id_assigned;
SELECT set_config('firefly_seed.target', :'seed_target', true) AS seed_target;

\echo '== Preflight refusals =='

DO $preflight$
DECLARE
    v_target text := current_setting('firefly_seed.target');
    v_org_name text;
    v_stray bigint;
BEGIN
    IF v_target NOT IN ('local', 'staging') THEN
        RAISE EXCEPTION 'firefly_staging_seed: refused — seed_target % is not a designated target', v_target;
    END IF;

    -- The fence counts rows. A role that RLS filters would count only what it can see.
    IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = current_user AND (rolsuper OR rolbypassrls)) THEN
        RAISE EXCEPTION 'firefly_staging_seed: refused — role % does not bypass RLS, so the fence could not see every row', current_user;
    END IF;

    -- The seed creates no tenant: Firefly must already be here.
    SELECT name INTO v_org_name FROM public.orgs WHERE id = '93667019-bd28-49b5-a688-acc9bb1e0a19'::uuid;
    IF v_org_name IS NULL THEN
        RAISE EXCEPTION 'firefly_staging_seed: refused — the Firefly org 93667019-bd28-49b5-a688-acc9bb1e0a19 is not in this database, and this seed creates no org';
    END IF;

    -- The first version of this seed made a separate staging org. No additional tenants: report it.
    IF EXISTS (SELECT 1 FROM public.orgs WHERE id = 'f17e0000-0000-4000-8000-000000000001'::uuid) THEN
        RAISE EXCEPTION 'firefly_staging_seed: refused — the retired separate staging org f17e0000-0000-4000-8000-000000000001 exists here; it must not, and this seed will not write beside it';
    END IF;

    -- Every seed id belongs to Firefly. One anywhere else is not this seed's to overwrite.
    v_stray := (SELECT count(*) FROM public.customer_person_role_types WHERE id::text LIKE 'f17e0000-0000-4000-8000-%' AND org_id IS DISTINCT FROM '93667019-bd28-49b5-a688-acc9bb1e0a19'::uuid)
        + (SELECT count(*) FROM public.departments WHERE id::text LIKE 'f17e0000-0000-4000-8000-%' AND org_id IS DISTINCT FROM '93667019-bd28-49b5-a688-acc9bb1e0a19'::uuid)
        + (SELECT count(*) FROM public.work_units WHERE id::text LIKE 'f17e0000-0000-4000-8000-%' AND org_id IS DISTINCT FROM '93667019-bd28-49b5-a688-acc9bb1e0a19'::uuid)
        + (SELECT count(*) FROM public.locations WHERE id::text LIKE 'f17e0000-0000-4000-8000-%' AND org_id IS DISTINCT FROM '93667019-bd28-49b5-a688-acc9bb1e0a19'::uuid)
        + (SELECT count(*) FROM public.location_program_categories WHERE id::text LIKE 'f17e0000-0000-4000-8000-%' AND org_id IS DISTINCT FROM '93667019-bd28-49b5-a688-acc9bb1e0a19'::uuid)
        + (SELECT count(*) FROM public.program_offerings WHERE id::text LIKE 'f17e0000-0000-4000-8000-%' AND org_id IS DISTINCT FROM '93667019-bd28-49b5-a688-acc9bb1e0a19'::uuid)
        + (SELECT count(*) FROM public.program_offering_variants WHERE id::text LIKE 'f17e0000-0000-4000-8000-%' AND org_id IS DISTINCT FROM '93667019-bd28-49b5-a688-acc9bb1e0a19'::uuid)
        + (SELECT count(*) FROM public.commercial_tuition_rates WHERE id::text LIKE 'f17e0000-0000-4000-8000-%' AND org_id IS DISTINCT FROM '93667019-bd28-49b5-a688-acc9bb1e0a19'::uuid)
        + (SELECT count(*) FROM public.financial_charge_templates WHERE id::text LIKE 'f17e0000-0000-4000-8000-%' AND org_id IS DISTINCT FROM '93667019-bd28-49b5-a688-acc9bb1e0a19'::uuid)
        + (SELECT count(*) FROM public.customers WHERE id::text LIKE 'f17e0000-0000-4000-8000-%' AND org_id IS DISTINCT FROM '93667019-bd28-49b5-a688-acc9bb1e0a19'::uuid)
        + (SELECT count(*) FROM public.persons WHERE id::text LIKE 'f17e0000-0000-4000-8000-%' AND org_id IS DISTINCT FROM '93667019-bd28-49b5-a688-acc9bb1e0a19'::uuid)
        + (SELECT count(*) FROM public.customer_persons WHERE id::text LIKE 'f17e0000-0000-4000-8000-%' AND org_id IS DISTINCT FROM '93667019-bd28-49b5-a688-acc9bb1e0a19'::uuid)
        + (SELECT count(*) FROM public.customer_members WHERE id::text LIKE 'f17e0000-0000-4000-8000-%' AND org_id IS DISTINCT FROM '93667019-bd28-49b5-a688-acc9bb1e0a19'::uuid)
        + (SELECT count(*) FROM public.person_child_relationships WHERE id::text LIKE 'f17e0000-0000-4000-8000-%' AND org_id IS DISTINCT FROM '93667019-bd28-49b5-a688-acc9bb1e0a19'::uuid)
        + (SELECT count(*) FROM public.opportunities WHERE id::text LIKE 'f17e0000-0000-4000-8000-%' AND org_id IS DISTINCT FROM '93667019-bd28-49b5-a688-acc9bb1e0a19'::uuid)
        + (SELECT count(*) FROM public.opportunity_persons WHERE id::text LIKE 'f17e0000-0000-4000-8000-%' AND org_id IS DISTINCT FROM '93667019-bd28-49b5-a688-acc9bb1e0a19'::uuid)
        + (SELECT count(*) FROM public.opportunity_customer_members WHERE id::text LIKE 'f17e0000-0000-4000-8000-%' AND org_id IS DISTINCT FROM '93667019-bd28-49b5-a688-acc9bb1e0a19'::uuid);
    IF v_stray > 0 THEN
        RAISE EXCEPTION 'firefly_staging_seed: refused — % row(s) in the seed id namespace belong to another org', v_stray;
    END IF;

    RAISE NOTICE 'firefly_staging_seed: seeding into % (93667019-bd28-49b5-a688-acc9bb1e0a19)', v_org_name;
END $preflight$;

\echo '== Fence: count every row that is not a seed row =='

CREATE TEMP TABLE firefly_seed_fence (
    schema_name  text   NOT NULL,
    table_name   text   NOT NULL,
    scope_column text,
    outside_rows bigint NOT NULL,
    PRIMARY KEY (schema_name, table_name)
) ON COMMIT DROP;

DO $fence_open$
DECLARE
    r record;
    v_scope text;
    v_count bigint;
BEGIN
    FOR r IN
        SELECT n.nspname AS schema_name, c.relname AS table_name, c.oid AS rel
        FROM pg_class c
        JOIN pg_namespace n ON n.oid = c.relnamespace
        WHERE c.relkind = 'r' AND n.nspname IN ('public', 'auth', 'storage')
        ORDER BY 1, 2
    LOOP
        -- Only the write-set tables hold seed rows; in every other table, every row is outside.
        v_scope := CASE
            WHEN r.schema_name = 'public' AND r.table_name IN ('customer_person_role_types', 'departments', 'work_units', 'locations', 'location_program_categories', 'program_offerings', 'program_offering_variants', 'commercial_tuition_rates', 'financial_charge_templates', 'customers', 'persons', 'customer_persons', 'customer_members', 'person_child_relationships', 'opportunities', 'opportunity_persons', 'opportunity_customer_members') THEN 'seed_rows'
            ELSE NULL
        END;
        IF v_scope IS NULL THEN
            EXECUTE format('SELECT count(*) FROM %I.%I', r.schema_name, r.table_name) INTO v_count;
        ELSE
            EXECUTE format('SELECT count(*) FROM %I.%I WHERE org_id IS DISTINCT FROM $1 OR id::text NOT LIKE $2', r.schema_name, r.table_name)
                INTO v_count USING '93667019-bd28-49b5-a688-acc9bb1e0a19'::uuid, 'f17e0000-0000-4000-8000-%';
        END IF;
    END LOOP;
END $fence_open$;

\echo '== Gates: which configuration the Firefly org already has =='

-- true = the org has none of its own, so the seed authors it; false = the seed uses the tenant's.
SELECT
    (NOT EXISTS (SELECT 1 FROM public.locations l WHERE l.org_id = '93667019-bd28-49b5-a688-acc9bb1e0a19'::uuid AND l.location_type = 'site' AND l.is_active AND l.id::text NOT LIKE 'f17e0000-0000-4000-8000-%'))::text AS seed_campuses,
    (NOT EXISTS (SELECT 1 FROM public.departments d WHERE d.org_id = '93667019-bd28-49b5-a688-acc9bb1e0a19'::uuid AND d.key = 'enrollment' AND d.id::text NOT LIKE 'f17e0000-0000-4000-8000-%'))::text AS seed_enrollment,
    ((NOT EXISTS (SELECT 1 FROM public.program_offerings o WHERE o.org_id = '93667019-bd28-49b5-a688-acc9bb1e0a19'::uuid AND o.id::text NOT LIKE 'f17e0000-0000-4000-8000-%')
     AND NOT EXISTS (SELECT 1 FROM public.financial_charge_templates t WHERE t.org_id = '93667019-bd28-49b5-a688-acc9bb1e0a19'::uuid AND t.id::text NOT LIKE 'f17e0000-0000-4000-8000-%')))::text AS seed_catalog,
    (NOT EXISTS (SELECT 1 FROM public.customer_person_role_types r WHERE r.org_id = '93667019-bd28-49b5-a688-acc9bb1e0a19'::uuid AND r.id::text NOT LIKE 'f17e0000-0000-4000-8000-%'
        AND r.key IN ('child', 'parent', 'guardian', 'emergency_contact', 'authorized_pickup', 'payer')))::text AS seed_role_types
\gset
\echo '   seed authors — campuses:' :seed_campuses ' enrollment:' :seed_enrollment ' catalog:' :seed_catalog ' roles:' :seed_role_types

